def count_files(folder):
    if 'contents' not in folder or not folder['contents']:
        return 1
    total = 0
    for item in folder['contents']:
        if 'contents' in item:
            total += count_files(item)
        else:
            total += 1
    return total

def is_safe(board, row, col):
    for r in range(row):
        if board[r] == col or abs(board[r] - col) == abs(r - row):
            return False
    return True

def backtrack(board, row):
    if row == len(board):
        return True
    for col in range(len(board)):
        if is_safe(board, row, col):
            board[row] = col
            if backtrack(board, row + 1):
                return True
            board[row] = 0
    return False

def solve_n_queens(n):
    board = [0] * n
    if backtrack(board, 0):
        return board
    return None
